import React, { useState, useContext } from "react";
import { AuthContext } from "./AuthContext";
import { useUser } from "./UserContext";

export default function Login({ onSwitchToSignUp }) {
    const [email, setEmail] = useState("");
    const [password, setPassword] = useState("");
    const [message, setMessage] = useState("");
    const { signIn } = useContext(AuthContext);
    const { fetchUser } = useUser();

    const handleLogin = async (e) => {
        e.preventDefault();

        try {
            const response = await fetch("https://us-central1-firstfb-b6f1e.cloudfunctions.net/signIn", {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify({ email, password }),
            });

            const data = await response.json();

            if (response.ok) {
                signIn(data.token);
                await fetchUser(data.token); // Fetch and store user immediately
                setMessage("Login successful!");
            } else {
                setMessage(data.error || "Login failed");
            }
        } catch (err) {
            setMessage("Network error");
            console.error(err);
        }
    };

    return (
        <div style={{ maxWidth: "300px", margin: "50px auto" }}>
            <h2>Login</h2>
            <form onSubmit={handleLogin}>
                <input
                    type="email"
                    placeholder="Email"
                    value={email}
                    onChange={(e) => setEmail(e.target.value)}
                    required
                    style={{ width: "100%", padding: "8px", marginBottom: "10px" }}
                />
                <input
                    type="password"
                    placeholder="Password"
                    value={password}
                    onChange={(e) => setPassword(e.target.value)}
                    required
                    style={{ width: "100%", padding: "8px", marginBottom: "10px" }}
                />
                <button type="submit" style={{ width: "100%", padding: "8px" }}>Login</button>
                <button
                    type="button"
                    style={{ marginTop: "10px", width: "100%", padding: "8px" }}
                    onClick={onSwitchToSignUp}
                >
                    New? Signup here
                </button>
            </form>
            {message && <p>{message}</p>}
        </div>
    );
}
