import React from "react";
import VimeoVideo from "./VimeoVideo";
import ProjectsPieChart from "./ProjectsPieChart";
import portrait from "../images/andrewImage.jpg";
import portraitHover from "../images/andrewImage2.jpg";

export default function IntroSection() {
    return (
        <div id="gridSection">
            <div className="gridBoxes" id="container1">
                <h1 className="itemA container1Grid">Andrew Meechan</h1>
                <h3 className="itemB container1Grid">University of Strathclyde</h3>
                <h3 className="itemC container1Grid">MEng Computer Science</h3>
                <h3 className="itemD container1Grid">4th Year Student</h3>

                <div id="portraitWrapper" className="itemE container1Grid">
                    <img src={portrait} alt="Andrew" className="top"/>
                    <img src={portraitHover} alt="Andrew hover"/>
                </div>
            </div>


            <div className="gridBoxes" id="container2">
                <ProjectsPieChart/>
            </div>

            <div className="gridBoxes" id="container3">
                <VimeoVideo></VimeoVideo>

            </div>

            <div className="gridBoxes" id="container4">
                <h1>Recent Events</h1>
                <h2>Completed the Starlinks Global Logistics Portal Project</h2>
            </div>


        </div>
    );
}
