import React, { useContext, useState } from "react";
import logo from "../images/logo3.png";
import { AuthContext } from "./accountManagement/AuthContext";
import PopUpForm from "./accountManagement/popUpForm";
import ConfirmSignOut from "./accountManagement/confirmSignOut";

export default function Navbar() {
    const { isSignedIn, signOut } = useContext(AuthContext);
    const [showForm, setShowForm] = useState(false);
    const [confirmSignOut, setConfirmSignOut] = useState(false);

    return (
        <div className="topnav">
            <img id="logo" src={logo} alt="logo" />

            <div className="nav-centre">
                <a className="active" href="index.html">Home</a>
                <a href="blog.html">Blog</a>
                <a href="games.html">Games</a>
                <a href="projects.html">Projects</a>
            </div>

            <div className="nav-right">
                <a className="contactNavButton" id="contactB" href="contact.html">Contact</a>
                <span className="divider">|</span>

                {!isSignedIn ? (
                    <>
                        <a
                            className="contactNavButton"
                            id="signInB"
                            href="#signin"
                            onClick={(e) => {
                                e.preventDefault();
                                setShowForm(true);
                            }}
                        >
                            Sign In
                        </a>
                        {showForm && <PopUpForm onClose={() => setShowForm(false)} />}
                    </>
                ) : (
                    <>
                        <a
                            id="signOutB"
                            className="contactNavButton"
                            href="#signout"
                            onClick={(e) => {
                                e.preventDefault();
                                setConfirmSignOut(true);
                            }}
                        >
                            Sign Out
                        </a>
                        {confirmSignOut && (
                            <ConfirmSignOut
                                onConfirm={() => {
                                    signOut();
                                    setConfirmSignOut(false);
                                }}
                                onCancel={() => setConfirmSignOut(false)}
                            />
                        )}
                    </>
                )}
            </div>
        </div>
    );
}
