import React, { useEffect, useRef, useState } from "react";
import "../styles/videosection.css";

export default function VideoSection() {
    const videoPlayerRef = useRef(null);
    const [currentIndex, setCurrentIndex] = useState(0);

    const videoPlaylist = [
        "/videos/rotaProDemo.mp4",
        "/videos/chessDemo.mp4",
        "/videos/aiDemo.mp4",
        "/videos/websiteDemo.mp4"
    ];

    // Update video when index changes
    useEffect(() => {
        const videoPlayer = videoPlayerRef.current;
        if (!videoPlayer) return;

        // swipe out
        videoPlayer.classList.add("swipe-out");

        const timer = setTimeout(() => {
            videoPlayer.src = videoPlaylist[currentIndex];
            videoPlayer.load();

            // conditional filter
            if (currentIndex === 3 || currentIndex === 0) {
                videoPlayer.style.filter = "blur(4px) brightness(0.6)";
            } else {
                videoPlayer.style.filter = "blur(3px) brightness(1)";
            }

            // swipe in
            videoPlayer.classList.remove("swipe-out");
            videoPlayer.classList.add("swipe-in");
            videoPlayer.play();

            setTimeout(() => {
                videoPlayer.classList.remove("swipe-in");
            }, 500);
        }, 500);

        return () => clearTimeout(timer);
    }, [currentIndex]);

    // Loop videos
    useEffect(() => {
        const videoPlayer = videoPlayerRef.current;
        if (!videoPlayer) return;

        const handleEnded = () => {
            setCurrentIndex((prev) => (prev + 1) % videoPlaylist.length);
        };

        videoPlayer.addEventListener("ended", handleEnded);
        return () => videoPlayer.removeEventListener("ended", handleEnded);
    }, [videoPlaylist.length]);

    return (
        <div className="video-wrapper">
            <div className="video-container">
                <video
                    ref={videoPlayerRef}
                    autoPlay
                    muted
                    loop
                    playsInline
                >


                    Your browser does not support the video tag.
                </video>
            </div>

            {/* dots */}
            <div className="video-dots">
                {videoPlaylist.map((_, index) => (
                    <div
                        key={index}
                        className={`dot ${index === currentIndex ? "active" : ""}`}
                        onClick={() => setCurrentIndex(index)}
                    ></div>
                ))}
            </div>

            <div className="video-text">
                <h1 id="nameText">Introducing Andrew</h1>
                <h2 id="courseText"></h2>
            </div>
        </div>
    );
}
