import React from "react";

export default function ConfirmSignOut({ onConfirm, onCancel }) {
    return (
        <div className="popup-overlay">
            <div className="popup-content">
                <h3>Are you sure you want to sign out?</h3>
                <div style={{ display: "flex", gap: "10px", marginTop: "15px" }}>
                    <button
                        style={{ padding: "8px 16px", background: "#bc0303", color: "white", border: "none", borderRadius: "6px" }}
                        onClick={onConfirm}
                    >
                        Yes, Sign Out
                    </button>
                    <button
                        style={{ padding: "8px 16px", background: "#ccc", border: "none", borderRadius: "6px" }}
                        onClick={onCancel}
                    >
                        Cancel
                    </button>
                </div>
            </div>
        </div>
    );
}
