// src/ProjectsPieChart.js
import React, { useState, useEffect } from "react";
import { PieChart, Pie, Cell, Tooltip, Legend, ResponsiveContainer } from "recharts";

export default function ProjectsPieChart() {
    const [projects, setProjects] = useState([]);
    const [message, setMessage] = useState("");

    const fetchProjects = async () => {
        try {
            const response = await fetch(
                "https://us-central1-firstfb-b6f1e.cloudfunctions.net/getAllProjects",
                {
                    method: "GET",
                    headers: { "Content-Type": "application/json" },
                }
            );

            const data = await response.json();

            if (response.ok) {
                setProjects(data.projects);
                setMessage("");
            } else {
                setMessage(data.error || "Failed to fetch projects");
            }
        } catch (err) {
            setMessage("Network error");
            console.error(err);
        }
    };


    useEffect(() => {
        fetchProjects();
    }, []);

    // Count number of projects per status
    const statusCounts = projects.reduce((acc, project) => {
        acc[project.status] = (acc[project.status] || 0) + 1;
        return acc;
    }, {});

    // Transform for Recharts
    const pieData = Object.entries(statusCounts).map(([status, count]) => ({
        name: status,
        value: count,
    }));

    // Colors for pie slices
    const COLORS = ["#2c8031", "#bc0303", "#FFBB28"];

    return (
        <div style={{ width: "100%", height: "35vh", margin: "30px auto", padding: "0" }}>
            <h2 style={{margin: "0"}}>Ongoing and Completed Projects</h2>
            {message && <p>{message}</p>}
            {pieData.length > 0 ? (
                <ResponsiveContainer>
                    <PieChart>
                        <Pie
                            data={pieData}
                            dataKey="value"
                            nameKey="name"
                            cx="50%"
                            cy="50%"
                            outerRadius={80}
                            fill="#8884d8"
                            label={({ payload }) => `${payload.name}: ${payload.value}`}
                        >
                            {pieData.map((entry, index) => (
                                <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />
                            ))}
                        </Pie>


                        <Tooltip />
                        <Legend />
                    </PieChart>
                </ResponsiveContainer>
            ) : (
                <p>No projects available</p>
            )}
        </div>
    );
}
